#![cfg(all(feature = "mock", feature = "testkit"))]
//! Property tests for the interception seam's no-cost guarantee.
//!
//! Everything in [`tinyflows::testkit`] is built on the engine consulting a
//! [`StepInterceptor`] around every node activation. That is only acceptable if
//! attaching one changes *nothing* when it declines to act — otherwise the
//! debugger is not observing a run, it is observing a different run.
//!
//! One hand-written graph cannot establish that. These assert it over graphs
//! nobody chose, generated by the same shape grammar the rest of the property
//! suite uses: for every graph the validator accepts, a plain run and a run
//! with an inert interceptor attached produce the same output.
//!
//! The generated leaves are pure control-flow nodes, so each run is a
//! deterministic function of its graph and the comparison is meaningful.

mod support;

use std::sync::{Arc, Mutex};

use async_trait::async_trait;
use proptest::prelude::*;
use serde_json::{Value, json};

use support::graphgen::{arb_shape, graph_of};
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::{CancellationToken, run, run_intercepted};
use tinyflows::interception::{StepAction, StepFrame, StepInterceptor, StepPhase};
use tinyflows::model::WorkflowGraph;
use tinyflows::observability::{NoopObserver, RunObserver};
use tinyflows::testkit::RunTracer;

/// An interceptor that looks at everything and changes nothing.
struct Inert;

#[async_trait]
impl StepInterceptor for Inert {
    async fn intercept(&self, _frame: StepFrame<'_>) -> StepAction {
        StepAction::Continue { state_patch: None }
    }
}

/// An interceptor that also *reads* every frame — resolving bindings and
/// scopes — without acting, so the cost of inspection is covered too.
struct Reads(Mutex<usize>);

#[async_trait]
impl StepInterceptor for Reads {
    async fn intercept(&self, frame: StepFrame<'_>) -> StepAction {
        let _ = frame.scope();
        let (_config, nulls) = frame.resolved_config();
        if frame.phase == StepPhase::Before {
            *self.0.lock().expect("lock") += nulls.len();
        }
        StepAction::Continue { state_patch: None }
    }
}

fn runtime() -> tokio::runtime::Runtime {
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("build runtime")
}

/// The output of a plain run.
fn plain(graph: &WorkflowGraph) -> Result<Value, String> {
    let compiled = compile(graph).map_err(|e| e.to_string())?;
    runtime().block_on(async {
        run(&compiled, json!({ "seed": 1 }), &mock_capabilities())
            .await
            .map(|outcome| outcome.output)
            .map_err(|e| e.to_string())
    })
}

/// The output of a run with `interceptor` attached.
fn intercepted(
    graph: &WorkflowGraph,
    interceptor: Arc<dyn StepInterceptor>,
) -> Result<Value, String> {
    let compiled = compile(graph).map_err(|e| e.to_string())?;
    runtime().block_on(async {
        run_intercepted(
            &compiled,
            json!({ "seed": 1 }),
            &mock_capabilities(),
            &(Arc::new(NoopObserver) as Arc<dyn RunObserver>),
            CancellationToken::new(),
            interceptor,
        )
        .await
        .map(|(outcome, _resumable)| outcome.output)
        .map_err(|e| e.to_string())
    })
}

/// Removes scheduler observations that may differ when interception adds an
/// await point without changing the workflow's data or routing.
fn semantic_result(result: Result<Value, String>) -> Result<Value, String> {
    fn strip_scheduler_fields(value: &mut Value) {
        match value {
            Value::Object(map) => {
                map.remove("_activation_step");
                map.remove("started_at_step");
                map.remove("polls");
                for child in map.values_mut() {
                    strip_scheduler_fields(child);
                }
            }
            Value::Array(items) => {
                for item in items {
                    strip_scheduler_fields(item);
                }
            }
            _ => {}
        }
    }

    result.map(|mut output| {
        strip_scheduler_fields(&mut output);
        output
    })
}

proptest! {
    #![proptest_config(ProptestConfig { cases: 48, ..ProptestConfig::default() })]

    /// An inert interceptor leaves the run state identical.
    #[test]
    fn an_inert_interceptor_never_changes_the_result(shape in arb_shape(3)) {
        let graph = graph_of(&shape);
        let expected = semantic_result(plain(&graph));
        let actual = semantic_result(intercepted(&graph, Arc::new(Inert)));
        prop_assert_eq!(
            expected,
            actual,
            "attaching an inert interceptor changed the run"
        );
    }

    /// Reading every frame — scopes, resolved config, null bindings — is also
    /// free of side effects.
    #[test]
    fn inspecting_every_frame_never_changes_the_result(shape in arb_shape(3)) {
        let graph = graph_of(&shape);
        let expected = semantic_result(plain(&graph));
        let actual = semantic_result(intercepted(&graph, Arc::new(Reads(Mutex::new(0)))));
        prop_assert_eq!(
            expected,
            actual,
            "inspecting frames changed the run"
        );
    }

    /// Tracing a run does not change it either, which is what makes a trace
    /// evidence about the run rather than about the tracing.
    #[test]
    fn tracing_never_changes_the_result(shape in arb_shape(3)) {
        let graph = graph_of(&shape);
        let expected = semantic_result(plain(&graph));

        let compiled = match compile(&graph) {
            Ok(compiled) => compiled,
            Err(err) => {
                prop_assert_eq!(expected, Err(err.to_string()));
                return Ok(());
            }
        };
        let tracer = Arc::new(RunTracer::new(Some(graph.clone())));
        let actual = semantic_result(runtime().block_on(async {
            run_intercepted(
                &compiled,
                json!({ "seed": 1 }),
                &mock_capabilities(),
                &(tracer.clone() as Arc<dyn RunObserver>),
                CancellationToken::new(),
                tracer.clone(),
            )
            .await
            .map(|(outcome, _resumable)| outcome.output)
            .map_err(|e| e.to_string())
        }));

        prop_assert_eq!(expected, actual, "tracing changed the run");

        // And the trace saw the run it claims to describe.
        let trace = tracer.trace();
        prop_assert!(
            !trace.steps.is_empty(),
            "a completed run should have recorded at least one step"
        );
    }
}
